function UIBattlingCtrlMgr:__delete()
    xTry(function()
        if self.coResetBattleDialogs then
            cs_coroutine.stop(self.coResetBattleDialogs)
            self.coResetBattleDialogs = nil
        end
        -- if not checkBool(self.notResetUICamera) then
        --     self:SetUICameraShowStatus(false)
        -- end
