---InsertBuffData
---添加 buffData
---@param data table @ 战斗中添加buff {uid = 1, buffId = 1, ownerId = 1, lay = 1(层数), remain = 1(持续回合数), star = 1, lv = 1}
function UIBattlingCtrlMgr:InsertBuffData(data)
    local _isContain = function(arg)
        for i, buffData in pairs(self.listRoleBuffDataBeforeInit) do
            if checkNumber(buffData.uid) == checkNumber(arg.uid) then
                return true
            end
        end
        return false
    end
    if IsNull(self.listRoleBuffDataBeforeInit) then
        self.listRoleBuffDataBeforeInit = {}
    end
    if not _isContain(data) then
        table.insert(self.listRoleBuffDataBeforeInit, data)
    end
end

---GetBuffDataBeforeRoleInit
---获取角色的缓存Buff
---@param roleUID integer
function UIBattlingCtrlMgr:GetBuffDataBeforeRoleInit(roleUID)
    if IsNull(self.listRoleBuffDataBeforeInit) or #self.listRoleBuffDataBeforeInit <= 0 then
        return nil
    end
    local buffList = {}
    for i = #self.listRoleBuffDataBeforeInit, 1, -1 do
        local buffData = self.listRoleBuffDataBeforeInit[i]
        if buffData.ownerId == roleUID then
            table.insert(buffList, buffData)
            table.remove(self.listRoleBuffDataBeforeInit, i)
        end
    end
    return buffList
end

