function UIBattlingCtrlMgr:InitListener()
    self.eventShowState = Events.AddListener(Constants.EventNames.UIBattingStoryRunning, Bind(self, self.DialogShowStateChange))
    self.eventChangeRoleAbilityStatus = Events.AddListener(Constants.EventNames.BattleChangeRoleAbilityStatus, Bind(self, self.UpdateRoleAbilityStatus))
    self.eventRoleAliveState = Events.AddListener(Constants.EventNames.UIBattlingUpdateCharacterAliveState, Bind(self, self.UpdateRoleAliveState))
    self.eventShowFadeOut = Events.AddListener(Constants.EventNames.UIBattleShowFadeOut, function()
        -- GameUtils.CommonScreenBlack(true, true, nil,nil, "FFFFFF")
        GameUtils.ShowBlackDuration(0.1,0,0.1,Color.white)
    end)
end

function UIBattlingCtrlMgr:RemoveListener()
    Events.RemoveListener(Constants.EventNames.UIBattingStoryRunning, self.eventShowState)
    Events.RemoveListener(Constants.EventNames.BattleChangeRoleAbilityStatus, self.eventChangeRoleAbilityStatus)
    Events.RemoveListener(Constants.EventNames.UIBattlingUpdateCharacterAliveState, self.eventRoleAliveState)
    Events.RemoveListener(Constants.EventNames.UIBattleShowFadeOut, self.eventShowFadeOut)
end

