function UIBattlingCtrlMgr:SaveUICameraData()
    local uiCamera = self:GetUICamera()
    if not IsNull(uiCamera) then
        self.uiCameraOrthographic = checkBool(uiCamera.orthographic)
        self.uiCameraFieldOfViewEx = checkNumber(uiCamera.fieldOfView)
    end
end

function UIBattlingCtrlMgr:SetUICameraShowStatus(isInBattle)
    local uiCamera = self:GetUICamera()
    if not IsNull(uiCamera) then
        if checkBool(isInBattle) then
            uiCamera.orthographic = false
            uiCamera.fieldOfView = 12
        else
            uiCamera.orthographic = checkBool(self.uiCameraOrthographic)
            uiCamera.fieldOfView = checkNumber(self.uiCameraFieldOfViewEx)
        end
    end
end

