---GetPlayerIDNum
---获取 玩家身份 Id
function UIBattlingCtrlMgr:GetPlayerIDNum()
    if self.strKey == Constants.KeyRandomSeed then return -1 end
    local playerId = self:GetPlayerUID()
    if playerId == -1 then return playerId end
    if checkInt(playerId) < 100000 then
        playerId = checkInt(playerId) + 100000
    end
    local strPart_1 = string.sub(checkString(playerId), 1, 4)
    local strPart_2 = string.sub(checkString(playerId), 5, #checkString(playerId))
    local showPart_1 = string.gsub(string.format("%#x", strPart_1), "0x", "")
    local showPart_2 = string.gsub(string.format("%#x", strPart_2), "0x", "")
    local showPart_3 = string.gsub(string.format("%#x", #checkString(playerId)), "0x", "")
    return { showPart_1, showPart_2, showPart_3 }
end

