---CreateSingleGameObject
---ResourceModule 方式加载游戏物体
function UIBattlingCtrlMgr:CreateSingleGameObject()
    self.mapSingleLoadGO = {}
    local sw = CS.System.Diagnostics.Stopwatch()
    local totalTime = 0
    local time = 0
    for i, v in pairs(Constants.UIResLoadGameObjectPath) do
        sw:Restart()
        self.mapSingleLoadGO[v] = UIBattlingTools.CreateGameObjectOfResourceModule(v)
        sw:Stop()
        time = time + sw.ElapsedMilliseconds
        if time > 100 then
            totalTime = totalTime + time
            time = 0
            coroutine.yield()
        end
    end
    -- print("load... CreateSingleGameObject", totalTime)
    
    ---创建跳字预设
    if isNull(self.listGOJumpNode) then self.listGOJumpNode = {} end
    
    for i = 1, 24 do
        local goJumpNode = UIBattlingTools.CreateGameObjectOfResourceModule(pathJumpNode)
        local jumpNodeLB = GetLuaBehaviour(goJumpNode, Constants.UIBattlingLuaTablePath.JumpNumNodePath)
        local luaJumpNode = jumpNodeLB.Env
        if not IsNull(luaJumpNode) then
            table.insert(self.listGOJumpNode, luaJumpNode)
        end
    end
end

function UIBattlingCtrlMgr:GetJumpNumNode()
    local lua
    if self.listGOJumpNode and #self.listGOJumpNode > 0 then
        lua = self.listGOJumpNode[1]
        table.remove(self.listGOJumpNode, 1)
    else
        local go = UIBattlingTools.CreateGameObjectOfResourceModule(pathJumpNode)
        local jumpNodeLB = GetLuaBehaviour(go, Constants.UIBattlingLuaTablePath.JumpNumNodePath)
        lua = jumpNodeLB.Env
    end
    return lua
end

function UIBattlingCtrlMgr:RecycleJumpNode(lua)
    if isNull(self.listGOJumpNode) or isNull(lua) then
        return
    end
    local go = lua.controller.gameObject
    go.transform.localScale = Vector3.zero
    table.insert(self.listGOJumpNode, lua)
end

function UIBattlingCtrlMgr:CreateGameObjectInCondition()
    xTry(function()
        --- 初始化战中 新手任务节点
        if UIBattlingDataMgr and BattlingCombatLevelMgr then
            local goPath = Constants.UIResLoadGameObjectInConditionPath.UIBattlingTrainingTargetPanel
            self.mapSingleLoadGO[goPath] = UIBattlingTools.CreateGameObjectOfResourceModule(goPath)
        end
    end)
    --- 展示技能进度
    if self.isShowRootSkillProcess then
        local goPath = Constants.UIBattleShowSkillProcess
        self.mapSingleLoadGO[goPath] = UIBattlingTools.CreateGameObjectOfResourceModule(goPath)
    end
    if UIBattleTrainFieldMgr then
        local goPath = Constants.UIResLoadGameObjectInConditionPath.TrainFieldBattleData
        self.mapSingleLoadGO[goPath] = UIBattlingTools.CreateGameObjectOfResourceModule(goPath)
    end
end

