---InitBattlingData
---初始化数据
---@param data table
function UIBattlingCtrlMgr:InitBattlingData(data)
    self:Init()
    self.strKey = data.randomSeed
    ---@type UIBattlingTools
    UIBattlingTools = import("Game.UI.UIBattling.UIBattlingTools")
    ---@type UIBattlingDataMgr
    UIBattlingDataMgr = import("Game.UI.UIBattling.UIBattlingDataMgr")
    UIBattlingDataMgr:Init()
    UIBattlingDataMgr:InitBattlingData(data)
    --- 设置新手任务数据 mgr
    if isNull(BattlingCombatLevelMgr) then
        ---@type BattlingCombatLevelMgr
        BattlingCombatLevelMgr = import("Game.UI.UIBattling.BattleCombat.BattlingCombatLevelMgr")
    end
    ---@type BattleEndMgr
    BattleEndMgr = import("Game.UI.UIBattling.BattleEnd.BattleEndMgr")
    BattleEndMgr:Init()
    self:InitPlayerInfoMgr(data)
    self:InitSettingMgr(data)
    self:InitGuideComponent(data.questId)
    self.mapCharacterShieldValue = {} -- 初始化缓存护盾值 map
    self:SetDamagingCharactorBattleFieldId(0)
    --- 初始化 阵营回合
    self.accumulateTurn = ConditionMgr.context.accumulateTurn or 0  -- 配合跨关卡累计回合数的三星条件。回合数只有显示是累计的，逻辑还是从0开始的
    self.curPlayerTeamRoundsNum = 0
    self.curEnemyTeamRoundsNum = 0
    self.goObjRoot = UIBattlingObjRoot.GetRoot() --- 设置 克隆游戏物体的集合点
    local screenWidth = Screen.width
    local screenHeight = Screen.height
    self.v2CurrentScreen = Vector2.New(screenWidth, screenHeight)
    self:SetBattleMode()
    self.uiType = UIBattleSettingMgr.UIType
    self.gameMode = BattleInfo.gameMode
    if BattleInfo:IsOnline()
        or self.uiType == UIBattleSettingMgr.EnumUIType.PVP
        or self.uiType == UIBattleSettingMgr.EnumUIType.PPVE then
        self:InitPVPMgr(data)
    end
    local type = GoodsUtils.GetIdType(checkNumber(data.questId), Constants.IDArea.Quests)
    if type == Constants.IDType.QuestTrainField then
        if isNull(UIBattleTrainFieldMgr) then
            ---@type UIBattleTrainFieldMgr
            UIBattleTrainFieldMgr =  import("Game.UI.UIBattling.Manager.UIBattleTrainFieldMgr")
            UIBattleTrainFieldMgr:Init()
        else
            UIBattleTrainFieldMgr:ResetFieldData()
        end
    end
    --todo TestTrainField
    --UIBattleTrainFieldMgr =  import("Game.UI.UIBattling.Manager.UIBattleTrainFieldMgr")
    --UIBattleTrainFieldMgr:Init()
end

