---CheckUnLockStateOfPlayerSetting
---获取玩家 战斗特殊设置 解锁状态
function UIBattlingCtrlMgr:CheckUnLockStateOfPlayerSetting()
    local questId = Constants.UNLOCK_PLAYERSETTING_QUESTID
    ---战斗模拟器跳过解锁检查
    if checkBool(BattleInfo.isSimulator) then
        return true
    end
    ---战斗录像
    if self.playMode and self.playMode == Constants.UIPlayMode.Replay then
        return true
    end
    ---战斗中只需要判断服务器是否解锁就行，如未解锁不应该进入战斗，只处理这种情况
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(questId)
    return isPass
end

