---CreaterDynamicAtlas
---创建动态图集
function UIBattlingCtrlMgr:CreaterDynamicAtlas()
    -- 创建动态图集 游戏物体 和 组件
    local goAssetPacker = KTool.CreateEmptyGameObject(UIModule.RootCanvas.gameObject, "AssetPacker")
    goAssetPacker.transform:SetAsFirstSibling()
    
    self.assetPacker = KTool.GetOrAddComponent(goAssetPacker, typeof(AssetPacker))
    self.assetPacker.useCache = false
    self.assetPacker.cacheName = "BattlingDynamicAtlas"
    local playerTeam = UIBattlingDataMgr:GetPlayerTeamList()
    if #playerTeam <= 0 then return end
    --- 本局人员技能卡图标
    for i = 1, #playerTeam do
        for j, skillData in pairs(playerTeam[i].skillList) do
            local skillCardData = UIBattlingTools.GetSkillCardInfoByTwoParam(skillData.skillId, 1)
            print(table.toString(skillCardData, "skillCardData"))
            if not IsNull(skillCardData) then
                local skillIconPath = skillCardData.skillIconPath
                for k = 1, #skillIconPath do
                    table.insert(self.dynamicAtlasList, skillIconPath[k])
                end
            end
        end
    end
    --- New_PVP
    if self.gameMode == Constants.GameMode.PVP or UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PVP then
        local enemyTeam = UIBattlingDataMgr:GetEnemyTeamList()
        for i = 1, #enemyTeam do
            for j, skillData in pairs(enemyTeam[i].skillList) do
                local skillCardData = UIBattlingTools.GetSkillCardInfoByTwoParam(skillData.skillId, 1)
                if not IsNull(skillCardData) then
                    local skillIconPath = UIBattlingTools.GetSkillCardInfoByTwoParam(skillData.skillId, 1).skillIconPath
                    for k = 1, #skillIconPath do
                        table.insert(self.dynamicAtlasList, skillIconPath[k])
                    end
                end
            end
        end
    end

    -- 猫球icon
    local initData = BattleInfo.initData
    if initData.playerCatTeam and initData.playerCatTeam[1] and table.count(initData.playerCatTeam[1]) > 0 then
        for i, catData in ipairs(initData.playerCatTeam[1]) do
            -- local catId = catData.catId
            -- local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting6033)
            -- local row = tableFile:GetByPrimaryKey(catId, false)
            -- local imgPath = string.format("%s.png", CS.ParseUtils.ParsePathName(row, "picture", ""))
            if catData.type == 1 then
                local ultraInfo = Tools.splitToNum( catData.finalSkills, '=')
                local skillId = ultraInfo[1]
                local skillStar = ultraInfo[2]

                local listSkillCardImgPath = UIBattlingTools.GetSkillCardInfoByTwoParam(skillId, skillStar).skillIconPath
                table.insert(self.dynamicAtlasList, listSkillCardImgPath[1])
            end
        end
    end
    if initData.enemyCatTeam and initData.enemyCatTeam[1] and table.count(initData.enemyCatTeam[1]) > 0 then
        for i, catData in ipairs(initData.enemyCatTeam[1]) do
            -- local catId = catData.catId
            -- local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting6033)
            -- local row = tableFile:GetByPrimaryKey(catId, false)
            -- local imgPath = string.format("%s.png", CS.ParseUtils.ParsePathName(row, "picture", ""))
            if catData.type == 1 then
                local ultraInfo = Tools.splitToNum( catData.finalSkills, '=')
                local skillId = ultraInfo[1]
                local skillStar = ultraInfo[2]

                local listSkillCardImgPath = UIBattlingTools.GetSkillCardInfoByTwoParam(skillId, skillStar).skillIconPath
                table.insert(self.dynamicAtlasList, listSkillCardImgPath[1])
            end
        end
    end
    
    local BattleDynamicUI = "BattleDynamicUI"
    self.assetPacker:AddTexturesByPresets(BattleDynamicUI)
    if not IsNull(self.assetPacker) then
        local isFinish = false
        self.assetPacker.onProcessCompleted = function()
            isFinish = true
            -- print("~___UIBattlingCtrlMgr:CreaterDynamicAtlas_DynamicAtlas Is Finished")
        end
        self.assetPacker:AddTexturesToPack(self.dynamicAtlasList)
        local sw = CS.System.Diagnostics.Stopwatch()
        sw:Restart()
        self.assetPacker:Process()
        --- 等待图集创建完毕
        while (not isFinish) do
            coroutine.yield()
        end
        sw:Stop()
        -- print("AP...Process:", sw.ElapsedMilliseconds)
    end
end

---SetImgByDynamicAtlas
---从动态图集获取 相应路径的图片
---@param img UnityEngine.UI.RawImage
---@param spritePath string
---@param rect UnityEngine.RectTransform
function UIBattlingCtrlMgr:SetImgByDynamicAtlas(img, spritePath, rect)
    if IsNull(img) or IsNull(spritePath) then return end
    if IsNull(self.assetPacker) then
        local transAssetPacker = UIModule.RootCanvas.transform:Find("AssetPacker")
        if not isNull(transAssetPacker) then
            local goAssetPacker = transAssetPacker.gameObject
            self.assetPacker = KTool.GetComponent(goAssetPacker, typeof(AssetPacker))
        end
    end
    if not IsNull(self.assetPacker) and not isNull(img) then
        -- print("[图集]", img, spritePath, rect)
        self.assetPacker:SetImage(img, spritePath, rect)
    end
end
