---InitPoolOBJOfBattling
---初始化 战斗需要粒子
function UIBattlingCtrlMgr:InitPoolOBJOfBattling()
    local sw = CS.System.Diagnostics.Stopwatch()
    local loaders = {}
    sw:Start()
    for poolName, objCount in pairs(UIPoolObjCreateCount) do
        local loader = ResourceModule.LoadBundleAsync(poolName, nil, true)
        table.insert(loaders, { _loader = loader, _poolName = poolName, _count = objCount })
    end
    while #loaders > 0 do
        for i = #loaders, 1, -1 do
            if not loaders[i]._loader.IsError and loaders[i]._loader.IsSuccess then
                local loader = loaders[i]
                self:InitPoolMgr(loader._poolName, loader._loader.ResultObject, loader._count, loader._loader)
                table.remove(loaders, i)
            end
        end
        coroutine.yield()
    end
    sw:Stop()
    -- print("load... UIBattlingPoolObjsTimeTotal", sw.ElapsedMilliseconds)
end

---InitPoolMgr
---初始化 对象池
---@param poolName string
---@param poolItemCount integer
---@param loader Engine.Modules.AbstractResourceLoader
function UIBattlingCtrlMgr:InitPoolMgr(poolName, go, poolItemCount, loader)
    PoolManager:InitPool(poolName, go, poolItemCount, loader)
    if IsNull(self.listObjPoolsName) then
        self.listObjPoolsName = {}
    end
    table.insert(self.listObjPoolsName, poolName)
end

---ClearObjPools
---清理对象池对象
function UIBattlingCtrlMgr:ClearObjPools()
    if IsNull(self.listObjPoolsName) then return end
    if #self.listObjPoolsName <= 0 then return end
    for key, value in pairs(self.listObjPoolsName) do
        PoolManager:TearDown(value)
    end
end

