---BackToFightReadyCommon
---通常战中中途退出逻辑
function UIBattlingCtrlMgr:BackToFightReadyCommon()
    local fightPreWarMgr = FightPreWarMgr:GetInstance() --- 战前管理类
    local serverData --- 战前请求服务器的 回调数据
    local battleData --- 服务器返回 的 战斗数据
    if fightPreWarMgr then
        serverData = FightPreWarMgr:GetInstance():GetFightData()
        if serverData then
            battleData = FightPreWarMgr:GetInstance():GetFightData().battleData
        end
    end
    local questId --- 关卡Id
    if fightPreWarMgr and serverData and battleData then
        questId = checkNumber(FightPreWarMgr:GetInstance():GetFightData().battleData.questId)
    end
    if questId and table.indexof(Constants.QUEST_DOUBLE_GUIDE, questId) then
        ---直接回主界面
        CS.Engine.UI.UIModule.Clear()
        GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome, hasExcluded = true }, nil, Constants.LoadingType.MainHome)
    else
        local questType = checkNumber(GoodsUtils.GetIdType(UIBattlingDataMgr.questId, Constants.IDArea.Quests)) -- 关卡类型
        if questType == Constants.IDType.QuestMaze then
            cs_coroutine.start(function() 
                cs_coroutine.yield_return(CS.Engine.Lib.Yielders.GetWaitForSeconds(0.3))
                GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome, hasExcluded = false }, nil, Constants.LoadingType.MainHome)
            end)
        elseif questType == Constants.IDType.QuestDirectionalFight then
            UIModule.RemoveDialogRecord(Constants.UITypeIds.DirectionalDialog)
            GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome, hasExcluded = false }, nil, Constants.LoadingType.MainHome)
        else
            GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome, hasExcluded = false }, nil, Constants.LoadingType.MainHome) 
        end
    end
    -- SpriteAtlasManager.Instance():Release(TAG_UIBATTlE_DIALOG)
end

function UIBattlingCtrlMgr:BackToFightReadyMaze()
    if not IsNull(self.co2Maze) then return end
    -- print("->UIBattlingCtrlMgr:BackToFightReadyMaze")
    self.co2Maze = cs_coroutine.start(function()
        Events.Broadcast(Constants.EventNames.PatrolEventBackFromFight)
        cs_coroutine.yield_return(CS.Engine.Lib.Yielders.GetWaitForSeconds(0.2))
        self:BackToFightReadyCommon()
        self.co2Maze = nil
    end)
end

---UpdateRoleAbilityStatus
---更新战场角色 能力状态
function UIBattlingCtrlMgr:UpdateRoleAbilityStatus()
    ---ClearList
    self.cannotClickFriendsList = nil
    self.cannotClickEnemiesList = nil
    self.cannotClickFriendsList = {}
    self.cannotClickEnemiesList = {}
    --- ResetList
    local roles = BattleViewMgr.roleViews
    for i, role in ipairs(roles) do
        local roleId = role.id -- 角色 Id
        local roleCamp = role.camp -- 角色阵营
        if role.statusAbility then
            if BattleInfo:IsUserCamp(roleCamp) then
                if not role:IsDead() and not role.statusAbility.canFriendClick then
                    table.insert(self.cannotClickFriendsList, roleId)
                end
            else
                if not role:IsDead() and not role.statusAbility.canEnemyClick then
                    table.insert(self.cannotClickEnemiesList, roleId)
                end
            end
        end
    end
    --- 检查当前 选中攻击目标 是否不可被选中
    local battlingDialog = self:GetBattlingDialog() -- UIBattlingDialog
    if battlingDialog then
        local curAttTargetId = battlingDialog.curAttTargetId -- 攻击目标的 roleId
        if curAttTargetId and self:GetRoleEnemyInNotClickList(curAttTargetId) then
            battlingDialog:ClearAttackTarget()
        end
    end
end

---GetRoleFriendInNotClickList
---获取该友方角色的 点击禁止 状态
---@param roleId number 角色 Id
function UIBattlingCtrlMgr:GetRoleFriendInNotClickList(roleId)
    if self.cannotClickFriendsList then
        for i, idInList in ipairs(self.cannotClickFriendsList) do
            if roleId == idInList then
                return true
            end
        end
    end
    return false
end

---GetRoleEnemyInNotClickList
---获取该敌方角色的 点击禁止 状态
---@param roleId number 角色 Id
function UIBattlingCtrlMgr:GetRoleEnemyInNotClickList(roleId)
    if self.cannotClickEnemiesList then
        for i, idInList in ipairs(self.cannotClickEnemiesList) do
            if idInList == roleId then
                return true
            end
        end
    end
    return false
end

function UIBattlingCtrlMgr:GetQuestWaveTipsData(questId, wave)
    wave = self.numBattleWaveEnemy
    local tipsVo = UIBattlingDataMgr:GetUIBattleTipsVo(UIBattlingDataMgr:GetBattleTipsValue(questId, wave))
    return checkTable(tipsVo)
end

