function UIBattlingCtrlMgr:UpdateRoleAliveState(roleId)
    local roleView = UIBattlingTools.GetRoleViewData(roleId)
    if roleView then
        local roleCampType = roleView.camp
        local isDead = roleView:IsDead()
        if not BattleInfo:IsUserCamp(roleCampType) and isDead then
            if self.tableBattlingDialog then
                self.tableBattlingDialog:CheckTargetIdAndCleanAttackTarget(roleId)
            end
        end
    end
end

function UIBattlingCtrlMgr:RecycleLoadGO()
    local objRoot = UIBattlingObjRoot.GetRoot()
    local _setGOPos = function(go, root)
        if isNull(go) then
            return
        end
        KTool.SetParent(go, root)
        go.transform.localPosition = Vector3.New(9999, 9999, 9999)
    end
    if self.mapSingleLoadGO then
        for i, go in pairs(self.mapSingleLoadGO) do
            _setGOPos(go, objRoot)
        end
    end
    if self.mapMultipleLoadGO then
        for i, goArr in pairs(self.mapMultipleLoadGO) do
            for i, go in pairs(goArr) do
                _setGOPos(go, objRoot)
            end
        end
    end
end

