------------ SkillAbandon ------------
function UIBattlingCtrlMgr:SetAbandonData(data)
    if not IsNull(data) then
        local result = {}
        for i, roleList in pairs(data) do
            result[checkNumber(i)] = roleList
        end
        self.abandonSkillCardList = result
        --clone(data)
    end
end

function UIBattlingCtrlMgr:CheckSkillCardLockStatus(skillCard)
    local skillRoleIndex = skillCard.skillCardRoleId
    -- local isEnough = self:IsRoleHasEnoughSPUseNormalSkill(skillRoleIndex)       -- 这里主要是检查红色sp的角色，是否还有sp可以释放小技能
    -- if not isEnough then
    --     return true
    -- end
    local skillIndex = skillCard.skillIndex
    local roleLockedList = self.abandonSkillCardList[skillRoleIndex]
    if isNull(roleLockedList) then return false end
    for i, index in pairs(roleLockedList) do
        if index == skillIndex then
            return true
        end
    end
    return false
end
