function UIBattlingCtrlMgr:SetAllSkillCardReceiverActive()
    local skillCards = checkTable(self:GetWholeSkillCards())
    for i, skillCard in pairs(skillCards) do
        if skillCard then
            skillCard:SetEventReceiverEnableState(true)
        end
    end
end


function UIBattlingCtrlMgr:GetWholeSkillCards()
    local skillPool = self.tableBattlingDialog.luaTableDialogSkillPool
    local _functionCollection = function(listSkillLocal)
        local list = {}
        if isNull(listSkillLocal) then return list end
        for i = 1, #listSkillLocal do
            if not IsNull(listSkillLocal[i].luaBehaviour) then
                table.insert(list, checkTable(listSkillLocal[i].luaBehaviour.Env))
            end
        end
        return list
    end
    local skillCardLineTop = _functionCollection(skillPool.skillPoolTransArrLineTop)
    local skillCardLineDown = _functionCollection(skillPool.skillPoolTransArrLineDown)
    return table.link(skillCardLineTop, skillCardLineDown)
end

function UIBattlingCtrlMgr:GetWholeEnableBuffNodes()
    local listShowNode = {}
    local roleBuffs = UIBattleBuffMgr.listRoleBuffs
    for i = 1, #roleBuffs do
        local node = checkTable(roleBuffs[i].luaBehaviour.Env)
        if node and checkBool(node.booleanInShow) then
            table.insert(listShowNode, node)
        end
    end
    return listShowNode
end

function UIBattlingCtrlMgr:GetWholeEnemySkill()
    return checkTable(self:GetBattlingInfoDialog().listCharacterCard)
end

function UIBattlingCtrlMgr:GetHighLightOBJ(idType, idNum)
    local HIGH_LIGHT_ID_TYPE = {
        SKILL_CARD_ENEMY = 1,
        SKILL_CARD_PLAYER = 2,
        BUFF = 3, 
    }
    idType = checkNumber(idType)
    idNum = checkNumber(idNum)
    local listOBJ = {}
    if idType == HIGH_LIGHT_ID_TYPE.SKILL_CARD_ENEMY then
        local listEnemySkill = self:GetWholeEnemySkill()
        for i = 1, #listEnemySkill do
            local skillCard = listEnemySkill[i]
            local skillId = checkNumber(skillCard.skillCardSkillId)
            if idNum == skillId then
                table.insert(listOBJ, skillCard)
            end
        end
        -- print("->listEnemySkill:", table.dump(listEnemySkill))
    elseif idType == HIGH_LIGHT_ID_TYPE.SKILL_CARD_PLAYER then
        local listSkillCard = self:GetWholeSkillCards()
        for i = 1, #listSkillCard do
            local skillCard = listSkillCard[i]
            local skillCardSkillId = checkNumber(skillCard.skillCardSkillId)
            if idNum == skillCardSkillId then
                table.insert(listOBJ, skillCard)
            end
        end
        -- print("->listSkillCard:", table.dump(listSkillCard))
    elseif idType == HIGH_LIGHT_ID_TYPE.BUFF then
        local listBuffs = self:GetWholeEnableBuffNodes()
        for i = 1, #listBuffs do
            local buffNode = listBuffs[i]
            local buffId = buffNode.buffId
            if idNum == buffId then
                table.insert(listOBJ, buffNode)
            end
        end
    end
    return listOBJ
end

function UIBattlingCtrlMgr:CleanTipsHighLight()
    if not IsNull(self.listTipsHighLight) and checkNumber(table.count(self.listTipsHighLight)) > 0 then
        for i = #self.listTipsHighLight, 1, -1 do
            local obj = self.listTipsHighLight[i]
            UIBattlingTools.RecyclePoolObj(obj)
        end
    end
    self.listTipsHighLight = nil
end

