function UIBattlingCtrlMgr:ResetBattleWithChangeElement(typeElement)
    typeElement = checkInt(typeElement)
    if BattleInfo then
        self:RefreshBattleEnemyElement(BattleInfo.initData, typeElement)
        BattleViewMgr:RestartBattle()
    end
end

function UIBattlingCtrlMgr:RefreshBattleEnemyElement(initData, typeElement)
    local dataEnemy = checkTable(initData.enemyTeam)
    for i = 1, #dataEnemy do
        for j = 1, #dataEnemy[i] do
            dataEnemy[i][j].attribute = checkInt(typeElement)
        end
    end
end

function UIBattlingCtrlMgr:AddRootOurTeamBuff(id, rectRoot)
    if isNull(self.listRootOurTeamBuffNode) then
        self.listRootOurTeamBuffNode = {}
    end
    local _isContain = function(argId)
        return not isNull(self.listRootOurTeamBuffNode[argId])
    end
    if not _isContain(id) then
        self.listRootOurTeamBuffNode[id] = rectRoot
    end
end

function UIBattlingCtrlMgr:CleanCatchDialog()
    xTry(function()
        for i, path in pairs(listDialogNeed2Catch) do
            path = checkString(path)
            local dialog = UIModule.GetPooledObject(path)
            if not isNull(dialog) then
                xTry(function()
                    UIModule.CurrentScreen.dialogs:Remove(dialog)
                end)
                UIModule.DestroyObject(dialog)
            end
        end
    end)
end

function UIBattlingCtrlMgr:PrepareAudioSheet()
    local CriWareUtils =  import('Game.Entry.CriWareUtilsFix')
    local menuPath = UISheets.UI_Menu.path
    local battlePath = UISheets.UI_Battle.path
    UISheets.UI_Menu.path = nil
    UISheets.UI_Battle.path = nil
    for k, v in pairs(UISheets.UI_Menu) do
        CriWareUtils.PrepareSheetById(v)
    end
    for k, v in pairs(UISheets.UI_Battle) do
        CriWareUtils.PrepareSheetById(v)
    end
    UISheets.UI_Menu.path = menuPath
    UISheets.UI_Battle.path = battlePath
end

--- 隐藏战斗界面（尾刀的时候调用，血条和跳字界面不隐藏）
function UIBattlingCtrlMgr:HideBattleUI()
    local mutexPageIds = {
        Constants.UITypeIds.UIBattlingDialog,
        Constants.UITypeIds.UIBattlingPVPInfoDialog,
    }
    UIBattlingTools.SetPagesShowState(mutexPageIds, false)
    if self.tableBattlingDialog then
        self.tableBattlingDialog.showSkillSequencePanelLB.Env:SetPanelShow(2, true)   -- 隐藏右下角的技能说明
    end
    if self.tableBattlingBattleInfoDialog then
        self.tableBattlingBattleInfoDialog:HideAllCharactorInfoNode()
    end
end

-- 回合开始时重置临时点数
function UIBattlingCtrlMgr:RoundStartResetTempSp()
    self.roleTempSpInfo = {}
    local roleViews = BattleViewMgr:FindCampRoles(BattleInfo.myCamp)
    for i, roleView in ipairs(roleViews) do
        local roleId = roleView.id
        self.roleTempSpInfo[roleId] = {
            roleView = roleView,
            realNum = roleView.ultraPoint,
            tempNum = 0,
        }
        -- print(string.format("[办卡] 重置 roleId %d   spType %d   realNum %d", roleId, roleView.ultraPointType, roleView.ultraPoint))
    end
end

--- 出牌时变更临时点数（现在只有出牌的地方调用了，合牌没有加）
---@param roleId any
function UIBattlingCtrlMgr:RoleAddTempSP(roleId)
    local info = self.roleTempSpInfo[roleId]
    if info.roleView.ultraPointType == 1 then
        -- 加临时点
        info.tempNum = info.tempNum + 1
    else
        -- 把一个真实点扣成临时点
        info.realNum = info.realNum - 1
        info.tempNum = info.tempNum + 1
        -- print(string.format("[办卡] 变更 roleId %d   realNum %d   tempNum %d", roleId, info.realNum, info.tempNum))
    end
end

-- 这里主要是检查红色sp的角色，是否还有sp可以释放小技能
function UIBattlingCtrlMgr:IsRoleHasEnoughSPUseNormalSkill(roleId)
    local info = self.roleTempSpInfo[roleId]
    -- print(string.format("[办卡] 检查 roleId %d   spType %d   realNum %d", roleId, info.roleView.ultraPointType, info.realNum))
    if info.roleView.ultraPointType == 1 then
        return true
    else
        return info.realNum > 0
    end
end

return UIBattlingCtrlMgr